 * The scanner for the small language described in the task. `scan(text)`
 * returns the list of tokens found in `text`, or throws a `LexError` at the
 * first point the input does not conform to the grammar.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCTUATORS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

export class LexError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

function isLetter(c) {
  return c !== undefined && /[A-Za-z]/.test(c)
}

function isIdentStart(c) {
  return c !== undefined && (isLetter(c) || c === '_')
}

function isIdentPart(c) {
  return c !== undefined && (isLetter(c) || c === '_' || /[0-9]/.test(c))
}

function isDecimalDigit(c) {
  return c !== undefined && /[0-9]/.test(c)
}

function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}

function isOctalDigit(c) {
  return c !== undefined && /[0-7]/.test(c)
}

function isBinaryDigit(c) {
  return c === '0' || c === '1'
}

class Scanner {
  constructor(text) {
    this.chars = Array.from(text)
    this.i = 0
    this.line = 1
    this.column = 1
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  atEnd() {
    return this.i >= this.chars.length
  }

  pos() {
    return { line: this.line, column: this.column }
  }

  fail(pos, reason) {
    throw new LexError(pos.line, pos.column, reason)
  }

  // Consumes and returns the current character, advancing line/column.
  advance() {
    const c = this.chars[this.i]
    this.i += 1
    if (c === '\n') {
      this.line += 1
      this.column = 1
    } else if (c === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column += 1
    }
    return c
  }

  skipWhitespaceAndComments() {
    for (;;) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        while (!this.atEnd() && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        const start = this.pos()
        this.advance()
        this.advance()
        let depth = 1
        while (depth > 0) {
          if (this.atEnd()) this.fail(start, 'unterminated block comment')
          if (this.peek() === '/' && this.peek(1) === '*') {
            this.advance()
            this.advance()
            depth += 1
          } else if (this.peek() === '*' && this.peek(1) === '/') {
            this.advance()
            this.advance()
            depth -= 1
          } else {
            this.advance()
          }
        }
        continue
      }
      break
    }
  }

