  // two digits of the same run. Returns the text read (possibly empty).
  readDigitRun(isDigit) {
    let text = ''
    let lastWasDigit = false
    for (;;) {
      const c = this.peek()
      if (isDigit(c)) {
        text += this.advance()
        lastWasDigit = true
      } else if (c === '_' && lastWasDigit && isDigit(this.peek(1))) {
        text += this.advance()
        lastWasDigit = false
      } else {
        break
      }
    }
    return text
  }

  scanNumber() {
    const start = this.pos()
    let text = this.advance() // the digit that started the token

    let prefixNoDigit = false

    if (text === '0' && (this.peek() === 'x' || this.peek() === 'X')) {
      text += this.advance()
      const digits = this.readDigitRun(isHexDigit)
      text += digits
      prefixNoDigit = digits === ''
    } else if (text === '0' && (this.peek() === 'b' || this.peek() === 'B')) {
      text += this.advance()
      const digits = this.readDigitRun(isBinaryDigit)
      text += digits
      prefixNoDigit = digits === ''
    } else if (text === '0' && (this.peek() === 'o' || this.peek() === 'O')) {
      text += this.advance()
      const digits = this.readDigitRun(isOctalDigit)
      text += digits
      prefixNoDigit = digits === ''
    } else {
      text += this.readDigitRun(isDecimalDigit)

      if (this.peek() === '.' && isDecimalDigit(this.peek(1))) {
        text += this.advance()
        text += this.readDigitRun(isDecimalDigit)
      }

      if (this.peek() === 'e' || this.peek() === 'E') {
        const afterSignIsDigit = (this.peek(1) === '+' || this.peek(1) === '-') && isDecimalDigit(this.peek(2))
        if (isDecimalDigit(this.peek(1)) || afterSignIsDigit) {
          text += this.advance()
          if (this.peek() === '+' || this.peek() === '-') text += this.advance()
          text += this.readDigitRun(isDecimalDigit)
        }
      }
    }

    let trailing = ''
    while (isIdentPart(this.peek())) trailing += this.advance()
    text += trailing

    if (prefixNoDigit || trailing !== '') {
      this.fail(start, `invalid number ${text}`)
    }

    return { kind: 'number', line: start.line, column: start.column, text }
  }

  scanIdent() {
    const start = this.pos()
    let text = ''
    while (isIdentPart(this.peek())) text += this.advance()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, line: start.line, column: start.column, text }
  }

  readHexDigits(count) {
    let text = ''
    for (let n = 0; n < count; n += 1) {
      if (!isHexDigit(this.peek())) return null
      text += this.advance()
    }
    return text
  }

  scanEscape(backslashPos) {
    if (this.atEnd()) return null // unterminated string, handled by caller
    const c = this.peek()
    if (c === 'n') { this.advance(); return '\n' }
    if (c === 't') { this.advance(); return '\t' }
    if (c === 'r') { this.advance(); return '\r' }
    if (c === '\\') { this.advance(); return '\\' }
    if (c === '"') { this.advance(); return '"' }
    if (c === '0') { this.advance(); return '\0' }
    if (c === 'x') {
      this.advance()
      const hex = this.readHexDigits(2)
      if (hex === null) this.fail(backslashPos, 'invalid escape \\x')
      return String.fromCharCode(parseInt(hex, 16))
    }
    if (c === 'u') {
      this.advance()
      if (this.peek() !== '{') this.fail(backslashPos, 'invalid escape \\u')
      this.advance()
      let hex = ''
      while (isHexDigit(this.peek())) hex += this.advance()
      if (hex === '' || this.peek() !== '}') this.fail(backslashPos, 'invalid escape \\u')
      this.advance()
      const codePoint = parseInt(hex, 16)
      if (codePoint > 0x10ffff) this.fail(backslashPos, 'invalid escape \\u')
      return String.fromCodePoint(codePoint)
    }
    this.fail(backslashPos, `invalid escape \\${c}`)
    return undefined
  }

  scanString() {
    const start = this.pos()
    this.advance() // opening quote
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(start, 'unterminated string')
      const c = this.peek()
      if (c === '"') {
        this.advance()
        break
      }
      if (c === '\n') {
        this.fail(this.pos(), 'newline in string')
      }
      if (c === '\\') {
        const backslashPos = this.pos()
        this.advance()
        const decoded = this.scanEscape(backslashPos)
        if (decoded === null) this.fail(start, 'unterminated string')
        value += decoded
        continue
      }
      value += this.advance()
    }
    return { kind: 'string', line: start.line, column: start.column, text: JSON.stringify(value) }
  }

  scanRawString() {
    const start = this.pos()
    this.advance() // r
    this.advance() // opening quote
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(start, 'unterminated string')
      const c = this.advance()
      if (c === '"') break
      value += c
    }
    return { kind: 'rawstring', line: start.line, column: start.column, text: JSON.stringify(value) }
  }

  scanPunct() {
    const start = this.pos()
    for (const p of PUNCTUATORS) {
      if (this.chars.slice(this.i, this.i + p.length).join('') === p) {
        for (let n = 0; n < p.length; n += 1) this.advance()
        return { kind: 'punct', line: start.line, column: start.column, text: p }
      }
    }
    return null
  }

  next() {
    this.skipWhitespaceAndComments()
    if (this.atEnd()) return null

    const c = this.peek()

    if (c === '"') return this.scanString()
    if (c === 'r' && this.peek(1) === '"') return this.scanRawString()
    if (isDecimalDigit(c)) return this.scanNumber()
    if (isIdentStart(c)) return this.scanIdent()

    const punct = this.scanPunct()
    if (punct) return punct

    const pos = this.pos()
    this.advance()
    this.fail(pos, `unexpected character ${c}`)
    return undefined
  }
}

export function scan(text) {
  const scanner = new Scanner(text)
  const tokens = []
  for (;;) {
    const token = scanner.next()
    if (token === null) break
    tokens.push(token)
  }
  return tokens
}
